:root {
  --bg: #ffffff;
  --text: #1f2937;
  --text-2: #4b5563;
  --muted: #6b7280;
  --border: #e5e7eb;
  --code-bg: #f6f8fa;
  --accent: #2563eb;
  --accent-soft: #eff6ff;
  --ok: #15803d;
  --ok-soft: #f0fdf4;
  --bad: #b91c1c;
  --bad-soft: #fef2f2;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", "Segoe UI", sans-serif;
  line-height: 1.75;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}
.wrap { max-width: 760px; margin: 0 auto; padding: 56px 24px 96px; }

.topline { height: 3px; background: var(--accent); position: fixed; top: 0; left: 0; right: 0; }

header h1 { font-size: 30px; font-weight: 700; margin: 0 0 10px; letter-spacing: -0.5px; }
header .sub { color: var(--muted); font-size: 15px; margin: 0; }
.meta { margin-top: 18px; font-size: 13px; color: var(--muted); border-left: 3px solid var(--border); padding-left: 12px; }
.meta a { color: var(--accent); text-decoration: none; }
.meta a:hover { text-decoration: underline; }

/* TOC */
nav.toc {
  margin: 32px 0 8px;
  padding: 20px 22px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: #fafafa;
}
nav.toc .toc-title { font-size: 13px; letter-spacing: 1px; color: var(--muted); margin: 0 0 10px; }
nav.toc ol { margin: 0; padding-left: 20px; }
nav.toc li { margin: 4px 0; }
nav.toc a { color: var(--text-2); text-decoration: none; }
nav.toc a:hover { color: var(--accent); }

section { margin-top: 52px; }
h2 {
  font-size: 22px; font-weight: 700; margin: 0 0 6px;
  padding-bottom: 10px; border-bottom: 1px solid var(--border);
}
h2 .num { color: var(--accent); margin-right: 8px; font-weight: 600; }
h3 { font-size: 17px; font-weight: 600; margin: 28px 0 8px; }
p { margin: 12px 0; }
strong { font-weight: 600; }
em { font-style: normal; color: var(--text-2); }

.lead { font-size: 16.5px; color: var(--text-2); }

ul, ol { padding-left: 22px; }
li { margin: 6px 0; }

.callout {
  margin: 18px 0; padding: 14px 16px;
  border: 1px solid var(--border); border-left: 3px solid var(--accent);
  background: var(--accent-soft); border-radius: 6px; font-size: 15px;
}
.callout .tag { font-size: 12px; letter-spacing: 1px; color: var(--accent); font-weight: 600; display: block; margin-bottom: 4px; }

pre {
  background: var(--code-bg); border: 1px solid var(--border);
  border-radius: 6px; padding: 14px 16px; overflow-x: auto;
  font-family: "SF Mono", ui-monospace, "JetBrains Mono", Menlo, Consolas, monospace;
  font-size: 13.5px; line-height: 1.6; margin: 14px 0;
}
code {
  font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
  font-size: 0.9em; background: var(--code-bg); padding: 1px 5px; border-radius: 4px;
}
pre code { background: none; padding: 0; }

table { border-collapse: collapse; width: 100%; margin: 16px 0; font-size: 14.5px; }
th, td { border: 1px solid var(--border); padding: 9px 12px; text-align: left; vertical-align: top; }
th { background: #fafafa; font-weight: 600; }
td code { white-space: nowrap; }

.objectives { background: #fafafa; border: 1px solid var(--border); border-radius: 8px; padding: 18px 22px; margin-top: 24px; }
.objectives .t { font-size: 13px; letter-spacing: 1px; color: var(--muted); margin-bottom: 8px; }
.objectives ul { margin: 0; }

/* quiz */
.quiz { margin-top: 52px; }
.quiz-head {
  position: sticky; top: 0; z-index: 5;
  background: rgba(255,255,255,0.96); border-bottom: 1px solid var(--border);
  padding: 10px 0; margin-bottom: 8px; display: flex; align-items: baseline; gap: 14px;
}
.quiz-head .score { font-size: 14px; color: var(--muted); }
.quiz-head .score b { color: var(--text); font-size: 16px; }

.level-block { margin: 34px 0; }
.level-label {
  font-size: 13px; letter-spacing: 1px; font-weight: 600; color: var(--accent);
  text-transform: uppercase; margin: 0 0 2px;
}
.level-desc { color: var(--muted); font-size: 14px; margin: 0 0 14px; }

.q {
  border: 1px solid var(--border); border-radius: 8px;
  padding: 18px 20px; margin: 16px 0; background: #fff;
}
.q .q-tag { font-size: 12px; color: var(--muted); letter-spacing: 0.5px; }
.q .q-text { font-weight: 600; margin: 6px 0 14px; }
.q .q-text .lv { display:inline-block; font-size:11px; color:var(--accent); border:1px solid var(--accent); border-radius:3px; padding:0 5px; margin-right:8px; font-weight:600; vertical-align:1px; }

.opts { display: flex; flex-direction: column; gap: 8px; }
.opt {
  display: block; width: 100%; text-align: left;
  border: 1px solid var(--border); border-radius: 6px; background: #fff;
  padding: 10px 14px; font-size: 15px; cursor: pointer; line-height: 1.5;
  transition: border-color .12s, background .12s;
  font-family: inherit; color: var(--text);
}
.opt:hover { border-color: #c7d2fe; background: #fbfcff; }
.opt .key { color: var(--muted); margin-right: 8px; font-weight: 600; }
.opt.correct { border-color: var(--ok); background: var(--ok-soft); }
.opt.wrong { border-color: var(--bad); background: var(--bad-soft); }
.opt.locked { cursor: default; }
.opt.locked:hover { border-color: var(--border); background: #fff; }
.opt.correct.locked:hover { border-color: var(--ok); background: var(--ok-soft); }

.ms-submit {
  margin-top: 12px; border: 1px solid var(--accent); color: var(--accent);
  background: #fff; border-radius: 6px; padding: 8px 18px; font-size: 14px; cursor: pointer;
}
.ms-submit:hover { background: var(--accent-soft); }
.ms-submit:disabled { opacity: .45; cursor: default; }
.ms-submit:disabled:hover { background: #fff; }

.feedback { display: none; margin-top: 14px; font-size: 14.5px; }
.feedback.show { display: block; }
.feedback .verdict { font-weight: 600; margin-bottom: 4px; }
.feedback.ok .verdict { color: var(--ok); }
.feedback.no .verdict { color: var(--bad); }
.feedback .expl { color: var(--text-2); }

.reveal-btn {
  margin-top: 12px; border: 1px solid var(--border); color: var(--text-2);
  background: #fff; border-radius: 6px; padding: 8px 18px; font-size: 14px; cursor: pointer;
}
.reveal-btn:hover { border-color: #c7d2fe; color: var(--accent); }
.reveal { display: none; margin-top: 12px; padding: 14px 16px; background: #fafafa; border: 1px solid var(--border); border-radius: 6px; font-size: 14.5px; color: var(--text-2); }
.reveal.show { display: block; }

footer { margin-top: 64px; padding-top: 20px; border-top: 1px solid var(--border); font-size: 13.5px; color: var(--muted); }
footer ol { padding-left: 20px; }
footer li { margin: 3px 0; }
footer a { color: var(--accent); text-decoration: none; }
footer a:hover { text-decoration: underline; }

