(function () {
  // 题型：mc=单选，ms=多选，open=开放（查看参考答案）
  var QUESTIONS = [
    /* ============ 一级：基础概念 ============ */
    { level: 1, type: 'mc',
      q: '一个 Agent Skill 最核心、必须存在的文件是哪一个？',
      options: ['README.md', 'SKILL.md', 'config.json', 'instructions.txt'],
      answer: 1,
      expl: 'SKILL.md 是唯一必需的文件，包含元数据（name / description）与指令正文。其余文件（脚本、参考、模板等）都是可选的。' },

    { level: 1, type: 'mc',
      q: 'SKILL.md 的 YAML frontmatter 中，哪些字段是<strong>必需</strong>的？',
      options: ['name 和 version', 'name 和 description', 'description 和 license', 'name、description 和 allowed-tools'],
      answer: 1,
      expl: '官方规定的最少元数据为 name 和 description；version、license、allowed-tools 等均为可选。' },

    { level: 1, type: 'mc',
      q: '关于 name 字段的约束，下列哪一项是<strong>错误</strong>的？',
      options: ['最多 64 个字符', '只能包含小写字母、数字和连字符', '不能包含保留字 anthropic 和 claude', '可以包含下划线和空格以提高可读性'],
      answer: 3,
      expl: 'name 只能使用小写字母、数字和连字符，不允许下划线和空格。例如 "My_PDF Tool" 不合规，应写作 my-pdf-tool。' },

    { level: 1, type: 'mc',
      q: '渐进式披露的第一层（发现阶段）在启动时加载的是什么？',
      options: ['完整的 SKILL.md 指令正文', '所有捆绑的脚本和资源', '每个技能的 name 与 description（元数据）', '用户的历史对话'],
      answer: 2,
      expl: '启动时只把每个技能的 name 和 description 预加载进系统提示，这是判断"何时该用哪个技能"所需的最少信息。' },

    { level: 1, type: 'mc',
      q: '渐进式披露的核心价值是什么？',
      options: [
        '一次性加载全部技能内容，确保智能体看到所有信息',
        '按需加载信息，从而能安装大量技能而只占用很少的上下文',
        '减少技能文件夹的数量',
        '强制智能体在每次任务前阅读所有技能'],
      answer: 1,
      expl: '完整指令只在任务需要时才加载，因此技能可携带几乎无限的内容，同时保持很小的上下文足迹。' },

    { level: 1, type: 'mc',
      q: '关于 description 字段，下列哪一项<strong>不符合</strong>官方约束？',
      options: ['必须非空', '最多 1024 个字符', '不能包含 XML 标签', '可以包含任意 HTML 标签来美化展示'],
      answer: 3,
      expl: 'description 必须非空、最多 1024 字符、且不能包含 XML 标签（HTML 标签同样不被允许）。' },

    /* ============ 二级：应用 ============ */
    { level: 2, type: 'mc',
      q: '下面的说法是否正确：description 应同时说明"这个技能做什么"和"何时使用"，因为智能体靠它决定是否触发该技能。',
      options: ['正确', '错误'],
      answer: 0,
      expl: '正确。name 与 description 是智能体触发决策的唯一依据，描述既要说功能也要说适用场景，否则容易漏触发或误触发。' },

    { level: 2, type: 'mc',
      q: '下列哪个 description 最符合编写最佳实践（能让智能体准确判断触发时机）？',
      options: [
        '一个很有用的技能。',
        'PDF：处理 PDF 文件。',
        '从 PDF 提取文本和表格，填写表单、合并文档。当用户处理 PDF、表单或需要文档抽取时使用。',
        '这是团队内部工具，非常重要。'],
      answer: 2,
      expl: '最佳实践要求 description 同时包含"做什么"（提取、填表、合并）与"何时用"（处理 PDF/表单/抽取时），且避免空泛。' },

    { level: 2, type: 'mc',
      q: '你的 SKILL.md 已超过 800 行，包含大量只在特定场景才用到的细节。最恰当的做法是？',
      options: [
        '继续全部塞进 SKILL.md，确保智能体一次读完',
        '把互斥或很少一起使用的上下文拆成独立文件（如 references/ 或 forms.md），并在 SKILL.md 中按名称引用',
        '删掉所有不重要的内容',
        '把细节写成代码注释'],
      answer: 1,
      expl: '这对应"为规模化构建结构"：当主文件臃肿时拆分为独立文件并按需引用，属于渐进式披露的第三层。' },

    { level: 2, type: 'mc',
      q: '为什么给列表排序、从 PDF 提取表单字段这类操作，应打包成脚本让智能体执行，而非让模型用 token 生成结果？',
      options: [
        '因为脚本看起来更专业',
        '因为模型完全无法完成这些任务',
        '因为代码执行更高效（token 生成昂贵）且结果更可靠（确定性）',
        '因为脚本不必进入上下文窗口'],
      answer: 2,
      expl: '打包代码的两大理由是效率与确定性。选项 D 只说了"机制"而非"动机"，且不是打包代码的根本原因。' },

    { level: 2, type: 'mc',
      q: '关于"从评估开始"（start with evaluation）这条最佳实践，正确的理解是？',
      options: [
        '先把所有技能写完，再统一做一次测试',
        '在代表性任务上运行智能体，观察它在哪里挣扎或缺少上下文，再有针对性地构建技能',
        '先设计用户界面，再写技能',
        '评估是可选的收尾步骤'],
      answer: 1,
      expl: '官方建议从能力缺口出发：先在真实任务上观察智能体的失败点，再增量地构建技能来填补缺口。' },

    /* ============ 三级：综合与设计 ============ */
    { level: 3, type: 'ms',
      q: '综合判断：下面的 frontmatter 存在哪些<strong>硬性违规</strong>？（可多选）',
      pre: '---\nname: My PDF Tool\ndescription: ""\n---',
      options: [
        'name 包含大写字母和空格，违反了"只能小写字母、数字、连字符"的约束',
        'description 为空，违反了"必须非空"的要求',
        '缺少 version 字段，而 version 是必填字段',
        'name 使用了保留字 claude'],
      answer: [0, 1],
      expl: '违规点有两条：name 应为 my-pdf-tool（去掉大写与空格）；description 不能为空。version 并非必填，且这里没有出现保留字 claude。此外从最佳实践看，description 还应说明"何时使用"。' },

    { level: 3, type: 'mc',
      q: '在 Claude Code 中，当企业级（Enterprise）技能与个人（personal）技能同名时，哪个会生效？',
      options: ['个人技能覆盖企业技能', '企业技能覆盖个人技能', '项目技能优先级最高', '两者会冲突报错'],
      answer: 1,
      expl: '同名时优先级为：企业级 &gt; 个人 &gt; 项目。插件技能使用 plugin-name:skill-name 命名空间，因此不会与其他层级冲突。' },

    { level: 3, type: 'open',
      q: '设计题：为团队设计一个"代码提交前安全检查"的技能。请说明你会在 SKILL.md 里写什么，以及 scripts/、references/、templates/ 各放什么，并解释这样划分如何体现渐进式披露。',
      answer:
        '参考答案（要点）：\n' +
        '1) SKILL.md（第一/二层）：写清技能用途（提交前检查）、触发时机（用户要求提交/审查改动时），并给出主流程——运行静态检查、检查硬编码密钥、核对测试是否更新，最后引用 scripts/ 与 references/ 中的文件。保持精简。\n' +
        '2) scripts/（第三层·执行）：放 check_secrets.py、run_lint.sh 等确定性脚本，由智能体直接执行，只把输出带入上下文。\n' +
        '3) references/（第三层·按需读）：放团队代码规范、常见误区的清单，仅在检查到对应情况时才读取。\n' +
        '4) templates/：放标准的提交信息模板、审查报告模板，供智能体复制填充。\n' +
        '渐进式体现：启动时只加载 name/description（发现），任务匹配后读入精简的 SKILL.md（激活），只有当检查真正需要时，才运行脚本或读取规范文档（执行）——避免一次性塞入全部上下文。' },

    { level: 3, type: 'open',
      q: '场景分析：你拿到一个来自陌生来源的技能，其中包含一个从外部 URL 拉取数据的脚本。在你把它用于生产环境之前，应该怎么做？请列出你的审计步骤。',
      answer:
        '参考答案（要点）：\n' +
        '1) 彻底阅读捆绑的全部文件：SKILL.md、脚本、图片与其它资源，判断它们是否与声明用途一致。\n' +
        '2) 重点检查：意外的网络调用、异常的文件访问模式、与声明用途不符的操作。\n' +
        '3) 对"从外部 URL 拉取数据"的部分格外警惕——拉取内容可能携带恶意指令，且依赖可能随时间被篡改。\n' +
        '4) 确认代码依赖的安全性与来源。\n' +
        '5) 原则：仅从可信来源使用技能，把安装技能当作安装软件一样谨慎；对含敏感数据或关键操作的生产系统尤其要克制。' }
  ];

  var scored = QUESTIONS.filter(function (q) { return q.type !== 'open'; });
  document.getElementById('total').textContent = scored.length;

  var score = 0;
  function bump(correct) {
    if (correct) score++;
    document.getElementById('score').textContent = score;
  }

  var root = document.getElementById('quiz-root');
  var levelTitles = { 1: '一级 · 基础概念', 2: '二级 · 应用', 3: '三级 · 综合与设计' };
  var levelDesc = {
    1: '考察对核心术语、字段规则与设计动机的准确理解。',
    2: '给定具体场景，判断该怎么做、识别正误。',
    3: '综合运用：合规判断、架构设计与安全审计。'
  };

  var KEYS = ['A', 'B', 'C', 'D', 'E', 'F'];

  QUESTIONS.forEach(function (q, qi) {
    var block = document.createElement('div');
    block.className = 'level-block';
    if (qi === 0 || QUESTIONS[qi - 1].level !== q.level) {
      var lh = document.createElement('div');
      lh.className = 'level-label'; lh.textContent = levelTitles[q.level];
      var ld = document.createElement('p');
      ld.className = 'level-desc'; ld.textContent = levelDesc[q.level];
      block.appendChild(lh); block.appendChild(ld);
    }

    var card = document.createElement('div');
    card.className = 'q';

    var qText = document.createElement('div');
    qText.className = 'q-text';
    qText.innerHTML = '<span class="lv">L' + q.level + '</span>' + q.q;
    card.appendChild(qText);

    if (q.pre) {
      var pre = document.createElement('pre');
      pre.textContent = q.pre;
      card.appendChild(pre);
    }

    var fb = document.createElement('div');
    fb.className = 'feedback';

    if (q.type === 'mc') {
      var wrap = document.createElement('div');
      wrap.className = 'opts';
      q.options.forEach(function (opt, oi) {
        var b = document.createElement('button');
        b.className = 'opt';
        b.innerHTML = '<span class="key">' + KEYS[oi] + '</span>' + opt;
        b.addEventListener('click', function () {
          if (b.classList.contains('locked')) return;
          var correct = oi === q.answer;
          // 锁定全部选项并标注
          Array.prototype.forEach.call(wrap.children, function (el, idx) {
            el.classList.add('locked');
            if (idx === q.answer) el.classList.add('correct');
          });
          if (!correct) b.classList.add('wrong');
          fb.className = 'feedback show ' + (correct ? 'ok' : 'no');
          fb.innerHTML = '<div class="verdict">' + (correct ? '✓ 正确' : '✗ 不正确') + '</div><div class="expl">' + q.expl + '</div>';
          bump(correct);
        });
        wrap.appendChild(b);
      });
      card.appendChild(wrap);
    } else if (q.type === 'ms') {
      var wrap2 = document.createElement('div');
      wrap2.className = 'opts';
      q.options.forEach(function (opt, oi) {
        var b = document.createElement('button');
        b.className = 'opt';
        b.setAttribute('data-oi', oi);
        b.innerHTML = '<span class="key">' + KEYS[oi] + '</span>' + opt;
        b.addEventListener('click', function () {
          if (b.classList.contains('locked')) return;
          b.classList.toggle('picked');
          if (b.classList.contains('picked')) {
            b.style.borderColor = 'var(--accent)';
            b.style.background = 'var(--accent-soft)';
          } else {
            b.style.borderColor = '';
            b.style.background = '';
          }
        });
        wrap2.appendChild(b);
      });
      var submit = document.createElement('button');
      submit.className = 'ms-submit';
      submit.textContent = '检查答案';
      submit.addEventListener('click', function () {
        if (submit.disabled) return;
        var chosen = [];
        Array.prototype.forEach.call(wrap2.children, function (el) {
          if (el.classList.contains('picked')) chosen.push(parseInt(el.getAttribute('data-oi'), 10));
        });
        chosen.sort();
        var truth = q.answer.slice().sort();
        var correct = chosen.length === truth.length && chosen.every(function (v, i) { return v === truth[i]; });
        Array.prototype.forEach.call(wrap2.children, function (el, idx) {
          el.classList.add('locked');
          el.style.borderColor = ''; el.style.background = '';
          if (q.answer.indexOf(idx) >= 0) el.classList.add('correct');
          else if (el.classList.contains('picked')) el.classList.add('wrong');
        });
        submit.disabled = true;
        fb.className = 'feedback show ' + (correct ? 'ok' : 'no');
        fb.innerHTML = '<div class="verdict">' + (correct ? '✓ 正确' : '✗ 不正确') + '</div><div class="expl">' + q.expl + '</div>';
        bump(correct);
      });
      card.appendChild(wrap2);
      card.appendChild(submit);
    } else { // open
      var rbtn = document.createElement('button');
      rbtn.className = 'reveal-btn';
      rbtn.textContent = '查看参考答案';
      var rev = document.createElement('div');
      rev.className = 'reveal';
      rev.innerHTML = q.answer.replace(/\n/g, '<br>');
      rbtn.addEventListener('click', function () {
        var show = !rev.classList.contains('show');
        rev.classList.toggle('show', show);
        rbtn.textContent = show ? '收起参考答案' : '查看参考答案';
      });
      card.appendChild(rbtn);
      card.appendChild(rev);
    }

    card.appendChild(fb);
    block.appendChild(card);
    root.appendChild(block);
  });
})();
